// Merge analysis results with enriched context from webhook
const analysis = $('HTTP Request - OpenAI Analysis').first().json;
const webhookData = $('Webhook - CI Failure').first().json;
const contextMeta = webhookData.contextMetadata || {};

// Build enriched analysis object for Slack
const enrichedAnalysis = {
  repository: analysis.repository || webhookData.repository,
  confidence: analysis.confidence || 0.5,
  analysis: analysis.analysis || 'Analysis unavailable',
  identified_cause: analysis.identified_cause || '',
  recommended_actions: analysis.recommended_actions || [],
  // Enriched context
  checkName: webhookData.checkName,
  headSha: webhookData.headSha,
  // Parse annotations from the log if available
  annotations: contextMeta.annotationsCount > 0 ? extractAnnotations(webhookData.log) : [],
  testFailures: contextMeta.testFailuresCount > 0 ? extractTestFailures(webhookData.log) : [],
  // PR context
  prContext: contextMeta.hasPRMetadata ? {
    number: webhookData.pullRequests?.[0] || 0,
    title: extractPRTitle(webhookData.log),
    author: extractPRAuthor(webhookData.log),
    branch: extractBranch(webhookData.log, 'head'),
    baseBranch: extractBranch(webhookData.log, 'base'),
    labels: contextMeta.prLabels || []
  } : null,
  // Workflow context
  workflowContext: contextMeta.hasWorkflowTiming ? {
    name: extractWorkflowName(webhookData.log),
    jobName: extractJobName(webhookData.log),
    duration: formatDuration(contextMeta.workflowDurationMs)
  } : null,
  dependencyChanges: contextMeta.dependencyChangesCount > 0 ? extractDependencyChanges(webhookData.log) : []
};

// Helper functions
function extractAnnotations(log) {
  const annotations = [];
  const regex = /([❌⚠️ℹ️]) (?:\*\*(.+?)\*\*\n)?📍 `(.+?):(\d+)`\n(.+?)(?=\n\n|$)/g;
  let match;
  while ((match = regex.exec(log)) !== null && annotations.length < 10) {
    annotations.push({
      level: match[1] === '❌' ? 'failure' : match[1] === '⚠️' ? 'warning' : 'notice',
      title: match[2] || '',
      path: match[3],
      startLine: parseInt(match[4]),
      message: match[5].trim()
    });
  }
  return annotations;
}

function extractTestFailures(log) {
  const failures = [];
  const regex = /### ❌ (.+?)(?:\s*\((.+?)\))?\n```\n([\s\S]+?)```/g;
  let match;
  while ((match = regex.exec(log)) !== null && failures.length < 10) {
    failures.push({
      testName: match[1].trim(),
      file: match[2] || '',
      error: match[3].trim()
    });
  }
  return failures;
}

function extractPRTitle(log) {
  const match = log.match(/\*\*Title:\*\* (.+?)\n/);
  return match ? match[1] : '';
}

function extractPRAuthor(log) {
  const match = log.match(/\*\*Author:\*\* @(.+?)\n/);
  return match ? match[1] : '';
}

function extractBranch(log, type) {
  const match = log.match(/\*\*Branch:\*\* (.+?) → (.+?)\n/);
  if (match) {
    return type === 'head' ? match[1] : match[2];
  }
  return '';
}

function extractWorkflowName(log) {
  const match = log.match(/\*\*Workflow:\*\* (.+?)\n/);
  return match ? match[1] : '';
}

function extractJobName(log) {
  const match = log.match(/\*\*Failed Job:\*\* (.+?)\n/);
  return match ? match[1] : '';
}

function formatDuration(ms) {
  if (!ms) return '';
  const seconds = Math.floor(ms / 1000);
  const minutes = Math.floor(seconds / 60);
  const remainingSeconds = seconds % 60;
  if (minutes > 0) {
    return `${minutes}m ${remainingSeconds}s`;
  }
  return `${seconds}s`;
}

function extractDependencyChanges(log) {
  const changes = [];
  const addedRegex = /➕ Added: `(.+?)@(.+?)`/g;
  const removedRegex = /➖ Removed: `(.+?)@(.+?)`/g;
  const updatedRegex = /🔄 Updated: `(.+?)` (.+?) → (.+)/g;

  let match;
  while ((match = addedRegex.exec(log)) !== null && changes.length < 10) {
    changes.push({ type: 'added', name: match[1], newVersion: match[2] });
  }
  while ((match = removedRegex.exec(log)) !== null && changes.length < 10) {
    changes.push({ type: 'removed', name: match[1], oldVersion: match[2] });
  }
  while ((match = updatedRegex.exec(log)) !== null && changes.length < 10) {
    changes.push({ type: 'updated', name: match[1], oldVersion: match[2], newVersion: match[3] });
  }
  return changes;
}

return [{ json: { analysis: enrichedAnalysis, webhookData: webhookData } }];

// Get the merged data from previous node
const data = $('Merge Analysis with Context').first().json;
const analysis = data.analysis;
const webhookData = data.webhookData;

// Get PR numbers (may be empty array)
const pullRequests = webhookData.pullRequests || [];

// If no PRs, return empty array (skip GitHub posting)
if (pullRequests.length === 0) {
  return [];
}

// Return items for each PR to post comment to
return pullRequests.map(prNumber => ({
  json: {
    repository: analysis.repository,
    pr_number: prNumber,
    analysis: analysis
  }
}));
